from datetime import date, timedelta


def bill_cycle(cycle: dict, events: list[dict]) -> dict:
    def half_up(num: int, den: int) -> int:
        return (2 * num + den) // (2 * den)

    start = date.fromisoformat(cycle["start"])
    end = date.fromisoformat(cycle["end"])
    days_in_cycle = (end - start).days
    plans = cycle["plans"]

    state = (
        None
        if cycle["plan"] is None
        else (cycle["plan"], cycle["seats"])
    )
    pending_plan = None
    usage_total = 0
    event_index = 0
    daily_states = []

    # Only the final state after all events of a day is billed.
    for offset in range(days_in_cycle):
        day_iso = (start + timedelta(days=offset)).isoformat()

        while (
            event_index < len(events)
            and events[event_index]["date"] == day_iso
        ):
            event = events[event_index]
            event_index += 1
            event_type = event["type"]

            if event_type == "change_plan":
                if state is not None:
                    current_plan, seats = state
                    new_plan = event["plan"]
                    if (
                        plans[new_plan]["seat_cents"]
                        < plans[current_plan]["seat_cents"]
                    ):
                        pending_plan = new_plan
                    else:
                        state = (new_plan, seats)
                        pending_plan = None

            elif event_type == "set_seats":
                if state is not None:
                    state = (state[0], event["seats"])

            elif event_type == "cancel":
                if state is not None:
                    state = None
                    pending_plan = None

            elif event_type == "resume":
                if state is None:
                    state = (event["plan"], event["seats"])

            elif event_type == "usage":
                usage_total += event["units"]

            else:
                raise ValueError(f"Unknown event type: {event_type!r}")

        daily_states.append(state)

    # Combine maximal runs of identical billed states.
    lines = []
    subscription_total = 0
    last_billed_state = None
    run_start = 0

    while run_start < days_in_cycle:
        run_state = daily_states[run_start]
        run_end = run_start + 1
        while (
            run_end < days_in_cycle
            and daily_states[run_end] == run_state
        ):
            run_end += 1

        if run_state is not None:
            plan_name, seats = run_state
            run_days = run_end - run_start
            cents = half_up(
                plans[plan_name]["seat_cents"] * seats * run_days,
                days_in_cycle,
            )
            lines.append({
                "kind": "subscription",
                "plan": plan_name,
                "seats": seats,
                "from": (start + timedelta(days=run_start)).isoformat(),
                "to": (start + timedelta(days=run_end)).isoformat(),
                "days": run_days,
                "cents": cents,
            })
            subscription_total += cents
            last_billed_state = run_state

        run_start = run_end

    due = subscription_total

    if last_billed_state is not None:
        last_plan = plans[last_billed_state[0]]
        overage_units = max(
            0, usage_total - last_plan["included_units"]
        )
        if overage_units > 0:
            cents = overage_units * last_plan["unit_cents"]
            lines.append({
                "kind": "overage",
                "units": overage_units,
                "cents": cents,
            })
            due += cents

    minimum_cents = 0
    if (
        last_billed_state is not None
        and subscription_total < cycle["min_cents"]
    ):
        minimum_cents = cycle["min_cents"] - subscription_total
        lines.append({"kind": "minimum", "cents": minimum_cents})
        due += minimum_cents

    coupon = cycle["coupon"]
    if coupon is not None:
        base = (
            subscription_total + minimum_cents
            if coupon["applies_to"] == "subscription"
            else due
        )
        discount = half_up(base * coupon["percent"], 100)
        if discount > 0:
            lines.append({"kind": "discount", "cents": -discount})
            due -= discount

    credit_used = min(cycle["credit_cents"], due)
    if credit_used > 0:
        lines.append({"kind": "credit", "cents": -credit_used})
        due -= credit_used

    tax = half_up(due * cycle["tax_permille"], 1000)
    if tax > 0:
        lines.append({"kind": "tax", "cents": tax})
        due += tax

    return {
        "lines": lines,
        "total_cents": due,
        "credit_remaining": cycle["credit_cents"] - credit_used,
        "next_plan": pending_plan,
    }
